package org.kanger.storage.dumb2;
import java.nio.file.*;
import java.util.*;
import org.kanger.*;
import org.kanger.ContextProductionCapture.Source;
import org.kanger.exception.*;
import org.kanger.enums.StorageLifecycleErrorCode;

/** One X witness crosses multiple trusted producers without losing original member Sources. */
public final class ContextTrustedWitnessCommitRunner {
    static int checks;static final int WORK=64000000;
    static final String BUNDLE="!$w seed(w,1)&&flag(w,1);",WARM="!@w seed(w,1)->warm(w,1);";
    static void require(boolean b,String why){++checks;if(!b)throw new AssertionError(why);}
    static void proof(ContextProductionFamilyAssembly.Evaluation e,boolean conflict,Map<UUID,ContextProductionInventory> members,long revision,long bundle,long warm){
        require(e.status==(conflict?ContextProductionFamilyAssembly.Status.COLLISION:ContextProductionFamilyAssembly.Status.FIXED_POINT),"complete trusted witness verdict: "+e.reason);
        if(!conflict){require(e.refutations.isEmpty(),"no invented witness collision");return;}
        require(e.barrier>0&&!e.refutations.isEmpty(),"collision after actual group-derived witness steps");
        for(ContextProductionFamilyAssembly.Refutation r:e.refutations){require(r.producer.localX&&r.producer.rule!=bundle&&r.producer.rule!=warm,"whole proposed negative rule is refuter, not an unrelated source");for(org.kanger.ContextProductionCapture.Support p:r.proofs){Set<UUID> foreign=new HashSet<>();int local=0;boolean original=false;for(Source s:p.sources){if(s.localX){++local;original|=s.rule==bundle;require(s.rule!=warm&&s.revision==revision&&s.view.equals(r.producer.view),"same pending X cut, irrelevant warm Source absent");}else{ContextProductionInventory inv=members.get(s.context);require(inv!=null&&s.revision==inv.revision&&s.view.equals("inventory:"+inv.fingerprint)&&inv.primary.stream().anyMatch(row->row.nativeRule==s.rule),"original whole member Source/pin/view/native primary ID");foreign.add(s.context);}}require(local==2&&original&&foreign.equals(members.keySet())&&p.sources.size()==4&&p.depth==3,"exact seed+candidate+both original producers at cumulative depth3");}}
    }
    static void one(boolean grouped,boolean reverse,boolean conflict)throws Exception{
        Path dir=Files.createTempDirectory("trusted-witness-write-");System.setProperty("user.home",dir.toString());ContextSevenPremiseNativeWriteRunner.create(dir,"A","!@w seed(w,1)->mid(w,1);");ContextSevenPremiseNativeWriteRunner.create(dir,"B","!@w mid(w,1)->done(w,1);");String candidate=conflict?"!@w done(w,1)->~flag(w,1);":"!@w done(w,1)->out(w,1);";Set<String> settled;List<RevisionRef> pins=new ArrayList<>();long after;
        try(ContextAutomaticPendingCommitRunner.Fixture f=new ContextAutomaticPendingCommitRunner.Fixture(dir,"X")){
            require(f.root.compile(BUNDLE+" "+WARM,null,false),"native X witness and independent supported self producer");for(String name:reverse?new String[]{"B","A"}:new String[]{"A","B"})ContextTrustedProductionCommitRunner.command(f,"ctx connect "+name+(grouped?" trust own":""));f.db.saveConnections(f.root);ContextProductionInventory before=ContextTrustedProductionCommitRunner.inventory(f);long revision=f.db.getRevision(),bundle=before.primary.stream().filter(r->r.origin.equals(BUNDLE)).findFirst().get().nativeRule,warm=before.primary.stream().filter(r->r.origin.equals(WARM)).findFirst().get().nativeRule;Map<UUID,ContextProductionInventory> members=new HashMap<>();for(ContextConnection c:f.db.dmzTopology()){pins.add(c.getTarget());members.put(c.getTarget().getContextId(),ContextProductionInventory.inspect(c.layer(),c.getTarget().getContextId(),c.getTarget().getRevision(),false,c.getInitialization(),1000));}
            Map<UUID,String> foreign=ContextTrustedProductionCommitRunner.foreign(f);ContextPendingProductionSnapshotSession.Decision diagnostic;Mind child=new Mind(f.root);require(child.compile(candidate,null,false),"prepare exact candidate child");try(ContextPendingProductionSnapshotSession lease=ContextPendingProductionSnapshotSession.open(f.db,child,1000)){diagnostic=lease.inspectAutomatic(16,16,16,65536,1000000,WORK,500000,WORK,WORK,100000);require(diagnostic.engine==ContextPendingProductionSnapshotSession.Engine.WITNESS,"native witness family selection");proof(diagnostic.witness,conflict,members,revision,bundle,warm);lease.requireCurrent();}finally{f.root.release(child);}
            f.guard.install();StorageLifecycleException failure=null;try{require(Boolean.TRUE.equals(f.root.query(candidate,null,false)),"actual safe witness publication");}catch(StorageLifecycleException e){failure=e;}finally{f.guard.restore();}
            require((failure!=null)==conflict,"actual witness admission matches fresh diagnostic");if(conflict){require(failure instanceof ContextWitnessProductionCommitException&&failure.getErrorCode()==StorageLifecycleErrorCode.STORAGE_CONTEXT_CONFLICT,"actual typed witness refutation");ContextProductionFamilyAssembly.Evaluation actual=((ContextWitnessProductionCommitException)failure).getFamilyEvaluation();require(actual!=diagnostic.witness,"historical diagnostic is not actual commit authority");proof(actual,true,members,revision,bundle,warm);require(f.db.getRevision()==revision&&ContextTrustedProductionCommitRunner.inventory(f).fingerprint.equals(before.fingerprint),"exact witness refusal leaves source/revision unchanged");}else require(f.db.getRevision()>revision,"safe native publication advances revision");
            settled=ContextSevenPremiseNativeWriteRunner.origins(ContextTrustedProductionCommitRunner.inventory(f));require(settled.equals(new HashSet<>(conflict?Arrays.asList(BUNDLE,WARM):Arrays.asList(BUNDLE,WARM,candidate))),"only whole candidate, no raw/group-derived primary import");require(ContextTrustedProductionCommitRunner.foreign(f).equals(foreign),"all initialized member inventories unchanged");after=f.db.getRevision();
        }
        try(ContextAutomaticPendingCommitRunner.Fixture f=new ContextAutomaticPendingCommitRunner.Fixture(dir,"X")){require(f.db.getRevision()>=after&&ContextSevenPremiseNativeWriteRunner.origins(ContextTrustedProductionCommitRunner.inventory(f)).equals(settled),"ordinary witness reopen exact primaries");List<RevisionRef> actual=new ArrayList<>();for(ContextConnection c:f.db.dmzTopology())actual.add(c.getTarget());require(actual.equals(pins),"ordinary witness reopen exact member pins");}
    }
    public static void main(String[] args){try{for(boolean g:new boolean[]{true,false})for(boolean r:new boolean[]{false,true})for(boolean c:new boolean[]{false,true})one(g,r,c);System.out.println("CONTEXT_TRUSTED_WITNESS_COMMIT_PASS checks="+(checks+ContextSevenPremiseNativeWriteRunner.checks));System.exit(0);}catch(Throwable e){e.printStackTrace();System.exit(1);}}
}
